    $('#orbit-work').innerHTML = running.map(item => { const stages = item.stages || [], doneStages = stages.filter(stage => stage.status === 'done').length, stalled = isStalledOrchestration(item); return `<article class="orbit-orchestration"><div class="orbit-orchestration-top"><span class="orbit-status wait">${esc(item.status)} · ${doneStages}/${stages.length || 1} stages</span><span class="orbit-subtle">${duration(liveElapsed(item))} live</span></div><h3 title="${esc(item.question)}">${esc(workTitle(item.question))}</h3><div class="orbit-stages">${stages.map(stage => `<div class="orbit-stage ${esc(stage.status)}">${esc(stage.name)}<br>${esc(stage.status)}</div>`).join('')}</div>${stalled ? `<section class="orbit-stalled"><b>Needs your attention</b>No new stage has returned for ${duration(liveElapsed(item))}. Nova has no orchestration retry or cancel control, so inspect the staged record before deciding the next local step.<div class="orbit-review-actions"><button class="orbit-button ghost stalled-inspect" data-task="${esc(item.id)}">Inspect current state</button><a class="orbit-button ghost" href="/runs">Open Runs</a></div></section>` : ''}</article>`; }).join('') || '<p class="orbit-subtle">No background work is running. Ask Nova a concrete project question to start.</p>';
