    document.querySelectorAll('.stalled-inspect').forEach(button => button.onclick = () => { const item = orchestrations.find(row => row.id === button.dataset.task); const stages = (item?.stages || []).map(stage => `${stage.name || 'Stage'}: ${stage.status || 'queued'}${stage.result ? `\n${stage.result}` : ''}`).join('\n\n'); showModal('Stalled local task', `Status: ${item?.status || 'unknown'} · ${duration(liveElapsed(item))} elapsed\n\n${stages || 'No stage detail has been returned yet.'}`); });
