  const refresh = async () => { const [consoleData, venture, orch, history, notifications, tasks] = await Promise.all([api('/api/console'),api('/api/venture'),api('/api/orchestrations?limit=30'),api('/api/history?limit=40'),api('/api/notifications'),api('/api/workspace/tasks')]); state = {console:consoleData,venture,orch,history,notifications,tasks}; render(); speakReadyChiefDelivery(); };
